            'max_results' => $options['max_results'] ?? null,
            'sort' => $options['sort'] ?? null,
            'verified' => $options['verified'] ?? null,
            'verified_pro' => $options['verified_pro'] ?? null,
            'trade_assurance' => $options['trade_assurance'] ?? null,
            'supplier_country' => $options['supplier_country'] ?? null,
