    /**
     * Scrape Yelp business reviews.
     *
     * Given a Yelp `business` (page URL, alias or business id), returns the `business` summary
     * (`businessId`, `alias`, `name`, `url`, `rating`, `reviewCount`, `ratingHistogram`,
     * `reviewsCountByLanguage`, `categories`, `city`, `region`) and its `reviews`: `id`, `url`,
     * `rating`, `text`, `language`, `publishedDate`, `date`, `user` (`name`, `location`,
     * `reviewCount`, `friendCount`, `photoCount`, `isElite`, `eliteYear`), `photos`, `videos`,
     * `reactions` (`helpful`, `thanks`, `loveThis`, `ohNo`), `ownerResponse`, `checkIns` and the
     * author's `previousReviews`. Sort like yelp.com (`relevance`, `newest`, `oldest`, `highest`,
     * `lowest`, `elites`), filter by `language`, star `rating`, a search `query` or `since` a
     * date, and page with `page` / `start` up to `max_reviews` per call. To continue, call again
     * with `start` = `nextStart` while `hasMore` is true: `nextStart` is the exact offset where
     * this call stopped. `nextPage` is only set when that offset falls on a page boundary (a
     * multiple of 10) and is null otherwise, because a page number would repeat reviews already
     * returned. Counts: `business.reviewCount` is the review count Yelp shows for the business;
     * `business.ratingHistogram` and `business.reviewsCountByLanguage` count the reviews in every
     * language, and Yelp updates them separately from `reviewCount`, so their sums can differ from
     * it by a few; `totalResults` is how many reviews match this call's `language`, `rating` and
     * `query` (the total that `start` pages through). A business with no reviews returns an empty
     * list; an unknown alias or URL is a 404. Billed one unit per 10 reviews returned
     * (`pagesFetched`).
     *
     * @param string $business The business: its Yelp page URL (https://www.yelp.com/biz/gary-
     * danko-san-francisco), its alias (gary-danko-san-francisco) or its business id
     * (WavvLdfdP6g8aZTtbBQHTw, the `businessId` of /local/yelp results). An id is answered
     * fastest; a URL or alias costs one business-page fetch first.
     * @param array{max_reviews?: int, page?: int, start?: int, sort?: string, language?: string, rating?: string, query?: string, since?: string, proxy_country?: string} $options
     *   - max_reviews: How many reviews to return (1-500). API default: 20.
     *   - page: 1-based Yelp review page to start from (10 reviews per page, like yelp.com's own
     * pages; 1-1000). To continue a previous response, pass its `nextStart` as `start`. API
     * default: 1.
     *   - start: 0-based review offset to start from instead of `page`. Pass `nextStart` from a
     * previous response to continue exactly where it stopped.
     *   - sort: Review order, as yelp.com's "Sort by" menu: relevance, newest, oldest, highest,
     * lowest, elites. `relevance` is Yelp's default order. API default: relevance.
     *   - language: Reviews written in this language (two-letter code: en, fr, de, es, ...). Yelp
     * lists one language at a time. Default: the language most of the business's reviews are in;
     * `business.reviewsCountByLanguage` lists the others.
     *   - rating: Only reviews with these star ratings, comma-separated (e.g. `1,2`).
     *   - query: Only reviews that mention this phrase (yelp.com's review search).
     *   - since: Only reviews written on or after this date (YYYY-MM-DD). With `sort=newest`
     * paging stops at the first older review.
     *   - proxy_country: Proxy country the request is sent from (ISO-2, e.g. 'US', 'DE'). Leave
     * blank: Yelp serves reviews the same to every country.
     * @return array<mixed>
     * Calls POST /local/yelp-reviews.
     */
    public function yelpReviews(string $business, array $options = []): array
    {
        return $this->postJson('/local/yelp-reviews', [
            'business' => $business,
            'max_reviews' => $options['max_reviews'] ?? null,
            'page' => $options['page'] ?? null,
            'start' => $options['start'] ?? null,
            'sort' => $options['sort'] ?? null,
            'language' => $options['language'] ?? null,
            'rating' => $options['rating'] ?? null,
            'query' => $options['query'] ?? null,
            'since' => $options['since'] ?? null,
            'proxy_country' => $options['proxy_country'] ?? null,
        ]);
    }

